// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzzTimestamp, uint64 fuzzBlockNumber) public {
        // 1. constrain to admissible domain: block.timestamp > 0 and pastBlockTime initial is 0.
        //    We need a timestamp that is NOT > pastBlockTime after the first successful call.
        //    pastBlockTime = block.timestamp + 1 after success, so a timestamp <= that will break the rule.
        vm.assume(fuzzTimestamp > 0);
        vm.assume(fuzzTimestamp < type(uint256).max);
        // ensure block.number mod 15 != 0 to avoid balance transfer which would complicate balance assertions
        vm.assume(fuzzBlockNumber % 15 != 0);

        // 2. set up environment: warp to a timestamp, set block number, deal 10 ether to self
        vm.warp(fuzzTimestamp);
        vm.roll(fuzzBlockNumber);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);

        // first call at timestamp T succeeds and sets pastBlockTime = T+1
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // store current pastBlockTime
        uint256 past = c.pastBlockTime();
        // warp to a timestamp <= past (the reference must revert, the bug succeeds)
        uint256 newTimestamp = bound(fuzzTimestamp, 1, past);
        vm.warp(newTimestamp);

        // second call: P reverts, M succeeds
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // 3. assertion: the reference must have reverted, so ok2 MUST be false for any admissible input.
        //    The buggy version will succeed (ok2 == true), breaking this rule.
        assertTrue(!ok2);
    }
}

