pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 prevTimestamp, uint256 nextTimestamp, uint64 amount) public {
        // Admissible domain: timestamps must be within reasonable bounds and nextTimestamp not in the past.
        bound(prevTimestamp, 0, type(uint64).max);
        bound(nextTimestamp, 0, type(uint64).max);

        // We need msg.value == 10 ether for the fallback require to pass; fuzz only amount for generality.
        vm.assume(amount >= 10 ether);

        // Ensure we can test the property across two calls: first call sets pastBlockTime based on prevTimestamp,
        // second call with nextTimestamp should revert if nextTimestamp <= prevTimestamp.
        vm.warp(prevTimestamp);
        vm.deal(address(this), amount);
        try c.f{value: 10 ether}() {}
        catch {}

        // Now warp to nextTimestamp and try the second fallback call.
        vm.warp(nextTimestamp);
        vm.deal(address(this), amount);
        bool ok = true;
        try c.f{value: 10 ether}() {}
        catch { ok = false; }

        // If nextTimestamp > prevTimestamp, the call should succeed; if nextTimestamp <= prevTimestamp, it must revert.
        // The buggy version removes the require, so it will succeed even when nextTimestamp <= prevTimestamp.
        bool shouldSucceed = nextTimestamp > prevTimestamp;
        assertTrue(ok == shouldSucceed);
    }
}

