pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 warpTime, uint256 rollNum, uint256 firstCallValue, uint256 secondCallValue) public {
        // Bound to admissible domain: warpTime > 0, rollNum < type(uint256).max to avoid overflow
        vm.assume(warpTime > 0);
        vm.assume(warpTime < type(uint64).max); // reasonable timestamp upper bound
        vm.assume(rollNum < type(uint64).max);

        // First call: set pastBlockTime under conditions that make it revert for reference if timestamp <= pastBlockTime
        // We want to create a scenario where after first call, pastBlockTime is set, then second call has block.timestamp <= pastBlockTime
        // Reference: second call reverts; Mutant: succeeds.

        // First call: set pastBlockTime with some timestamp and block number
        vm.warp(warpTime);
        vm.roll(rollNum);
        vm.deal(address(this), firstCallValue);
        (bool firstOk, ) = address(c).call{value: firstCallValue}("");
        vm.assume(firstOk); // ensure first call succeeds (both versions)

        uint256 pastTimeAfterFirst = c.pastBlockTime();

        // Second call: ensure block.timestamp <= pastBlockTime to trigger the difference
        // We set timestamp <= pastBlockTime. Since pastBlockTime was set to warpTime+1 (if first call succeeded),
        // we warp to a time <= warpTime+1. Let's warp to warpTime (which is < warpTime+1, so <= pastBlockTime).
        // But we could also have warpTime exactly equal to pastBlockTime-1 or less. The key: block.timestamp <= pastBlockTime.
        // To generalize: we just need second call's block.timestamp <= pastBlockTime. We'll compute a new warp <= pastBlockTime.

        // Bound second call's timestamp to be <= pastBlockTime (non-strict). Since pastBlockTime = warpTime+1 if first succeeded,
        // we need warp2 <= warpTime+1. We'll let the fuzzer pick warp2, but constrain it.
        uint256 warp2Bound = pastTimeAfterFirst;
        vm.assume(warp2Bound > 0);
        // We'll directly use warpTime for simplicity, as it's <= pastBlockTime-1 if first call set pastBlockTime = warpTime+1.
        // But the fuzzer already gave us warpTime; we reuse it as the second call's timestamp. This is guaranteed <= pastBlockTime
        // because pastBlockTime = warpTime+1, and warpTime < warpTime+1.

        // However, we must allow the fuzzer to also vary the second call's value and block number.
        // We'll use the same warpTime for second call (timestamp <= pastBlockTime). That's guaranteed if first call succeeded.
        // But what if first call didn't succeed? We assumed firstOk. Then pastBlockTime is set to warpTime+1.
        // So second call at warpTime has block.timestamp = warpTime < warpTime+1 = pastBlockTime, thus timestamp < pastBlockTime (strictly less), which is the condition: not strictly greater.
        // Reference should revert; mutant should succeed.

        vm.warp(warpTime); // reuse original timestamp, which is now <= pastBlockTime
        vm.roll(rollNum + 1); // change block number to avoid reentrancy guard? No guard. Just vary.
        vm.deal(address(this), secondCallValue);

        // Use try/catch to detect revert
        bool referenceReverted = false;
        try c.fallback{value: secondCallValue}() {
            // Reference should revert, so this block not executed if reference works correctly
        } catch {
            referenceReverted = true;
        }

        // For the mutant, the same call should NOT revert (since timestamp check removed).
        // We can't directly distinguish here because we only have one contract instance.
        // SOLUTION: Deploy a mutant instance? Not allowed. We need to observe the property on c.
        // The property must be: On the reference, second call reverts when block.timestamp <= pastBlockTime.
        // We assert that the call DID revert for the reference (since we are testing the reference).
        // But the test must PASS on the reference and FAIL on the buggy version. 
        // If we deploy reference, assert that it reverts — that's a passing test for reference.
        // For buggy version, the same call would NOT revert, so the assertion "it reverts" would fail.
        // Thus: assertTrue(referenceReverted) is correct.

        assertTrue(referenceReverted);
    }
}

