pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 roll, uint256 warp) public {
        // The admissible domain: we can only call fallback if it accepts 10 ether.
        // The transfer also requires block.timestamp > pastBlockTime.
        // To make a valid call, we must ensure block.timestamp > pastBlockTime (initially 0).
        // pastBlockTime is initially 0. warp > 0 is required, but we can also set a nonzero roll.
        // To trigger the difference in pastBlockTime, we just need a successful fallback call.
        // We restrict roll so it's not 0 (block.number must be > 0) and warp > 0.
        vm.assume(roll > 0);
        vm.assume(warp > 0);
        vm.roll(roll);
        vm.warp(warp);

        // Fund a caller with 10 ether and call fallback.
        address caller = address(0x123);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "Call failed");

        // pastBlockTime is now either warp + 1 (ref) or warp + 2 (bug).
        // The difference does not affect the balance transfer condition block.number % 15 == 0,
        // but it does affect subsequent calls. To observe the difference directly,
        // we note that right after the call, pastBlockTime equals warp + 1 in ref,
        // and warp + 2 in bug. So pastBlockTime - warp = 1 (ref) or 2 (bug).
        // We assert that pastBlockTime - warp == 1.
        // This is a general rule the reference satisfies, and the bug breaks.
        assertTrue(c.pastBlockTime() - warp == 1);
    }
}

