import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 caller) public {
        vm.assume(caller != address(0) && caller != address(this));
        // Warp to a fresh timestamp, roll to a block divisible by 15
        uint256 t = 1000;
        vm.warp(t);
        vm.roll(15);

        // First call: meet the 10 ether requirement and execute the transfer
        address sender = address(uint160(caller));
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        c.f{value: 10 ether}();

        // Immediately attempt a second call in the same block
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        bool secondCallSuccess;
        try c.f{value: 10 ether}() {
            secondCallSuccess = true;
        } catch {
            secondCallSuccess = false;
        }

        // Rule: on the second call, the reference must revert (not bypass the timestamp guard),
        // but the bug allows it to succeed.
        assertFalse(secondCallSuccess);
    }
}

