pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        // Restrict to future timestamps, wide domain
        vm.assume(timestamp > 1);
        vm.assume(blockNumber > 0);
        vm.roll(blockNumber);
        vm.warp(timestamp);

        address sender = address(0x1234);
        vm.deal(sender, 100 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback failed");

        // General rule: pastBlockTime must be set to block.timestamp + 1 after every successful fallback call.
        // The buggy version does not differ in this state update, so this property passes on both,
        // failing to distinguish the missing payout.
        // To actually target the payout difference, we need a property about the contract's balance
        // when the payout is triggered vs. not triggered.
        // However, the previous attempts tested exactly those balance properties and they passed on the mutant too
        // because the fuzzer likely never hit block.number % 15 == 0 within the restricted domain.
        // Widening the domain with no block-number constraints ensures the fuzzer explores both conditions.
        if (blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0, "Balance must be zero after payout on mod-15 block");
        } else {
            assertEq(address(c).balance, 10 ether, "Balance must remain 10 ether on non-mod-15 block");
        }
    }
}

