import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 totalReceived;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 bnum, bool prime) public {
        uint256 amount = 10 ether;
        vm.assume(bnum > 0);
        vm.roll(bnum);
        vm.warp(1);

        address sender = address(0x123456);
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "call must succeed");

        totalReceived += amount;

        // The invariant: contract balance never exceeds total received payments.
        // Reference C transfers the balance when block.number % 15 == 0, so balance goes to 0, which is <= totalReceived.
        // Buggy M never transfers, so its balance accumulates and eventually exceeds totalReceived after one or more payments.
        assertTrue(address(c).balance <= totalReceived);
    }
}
